fn poll(self: Pin<&mut Self>, cx: &mut Context<'_>) -> Poll<io::Result<()>> {
    let me = self.project();

    // Allocate an array of IoSlices to fill with the chunks of the buffer.
    const N: usize = 16;
    let mut slices = [IoSlice::new(&[]); N];

    // Check whether the writer supports vectored writes.
    let is_write_vectored = me.writer.is_write_vectored();

    while me.buf.has_remaining() {
        if is_write_vectored {
            // Fill the slices with the chunks of the buffer; if the buffer
            // is fragmented, this allows the writer to write all of them
            // in a single syscall.
            let n = me.buf.chunks_vectored(&mut slices);
            if n > 1 {
                let written =
                    ready!(Pin::new(&mut *me.writer).poll_write_vectored(cx, &slices[..n])?);
                me.buf.advance(written);
                if written == 0 {
                    return Poll::Ready(Err(io::ErrorKind::WriteZero.into()));
                }
                continue;
            }
        }

        let n = ready!(Pin::new(&mut *me.writer).poll_write(cx, me.buf.chunk())?);
        me.buf.advance(n);
        if n == 0 {
            return Poll::Ready(Err(io::ErrorKind::WriteZero.into()));
        }
    }

    Poll::Ready(Ok(()))
}

